package com.maviinamane.delivery;
import java.math.BigDecimal; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @CrossOrigin(origins="${app.cors-origin:http://localhost:3000}") public class DeliveryChargeController{private final DeliveryChargeService service;public DeliveryChargeController(DeliveryChargeService s){service=s;}@GetMapping("/api/admin/delivery-charges")public List<DeliveryChargeConfig> all(@RequestParam(required=false)String type){return service.all(type);}@PostMapping("/api/admin/delivery-charges")@ResponseStatus(HttpStatus.CREATED)public DeliveryChargeConfig create(@RequestBody DeliveryChargeConfig v){return service.save(v);}@PutMapping("/api/admin/delivery-charges/{id}")public DeliveryChargeConfig update(@PathVariable String id,@RequestBody DeliveryChargeConfig v){v.setId(id);return service.save(v);}@DeleteMapping("/api/admin/delivery-charges/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable String id){service.delete(id);}@PostMapping("/api/delivery-charges/calculate")public DeliveryChargeService.Quote calculate(@RequestBody CalculateRequest r){return service.calculate(r.distanceKm(),r.weightKg());}public record CalculateRequest(BigDecimal distanceKm,BigDecimal weightKg){}
}
